// Process P acquires a file lock first
lock(file_lock);
read_config();

// While still holding file_lock, P now requests a database connection
connection = acquire(db_connection_pool);   // may block here, file_lock stays held
use_connection(connection);

release(db_connection_pool, connection);
unlock(file_lock);

